{"command": "# Test case where stdout is NOT a tty but stdin is? Need custom python pty harness
python3 <<'PY'
import os, pty, subprocess, select, time, fcntl, sys

def test_case(name, use_pty_stdin, use_pty_stdout, use_pty_stderr):
    print(f"\n=== {name} ===")
    # We'll use script-like: create ptys as needed, pipes otherwise
    # Simplest: use subprocess with stdin/stdout either pty slave or pipe
    masters = {}
    slaves = {}
    for stream in ['stdin','stdout','stderr']:
        use_pty = {'stdin':use_pty_stdin,'stdout':use_pty_stdout,'stderr':use_pty_stderr}[stream]
        if use_pty:
            m,s = pty.openpty()
            masters[stream]=m
            slaves[stream]=s
        else:
            masters[stream]=None
            slaves[stream]=subprocess.PIPE

    # For stdin pty, we need to keep master open; for stdout/stderr pty, need to read
    p = subprocess.Popen(["./executable","--on-load","Quit"],
                         stdin=slaves['stdin'] if masters['stdin'] is not None else subprocess.PIPE,
                         stdout=slaves['stdout'] if masters['stdout'] is not None else subprocess.PIPE,
                         stderr=slaves['stderr'] if masters['stderr'] is not None else subprocess.PIPE,
                         close_fds=True)
    # close slaves in parent
    for s in slaves.values():
        if s is not None and s != subprocess.PIPE:
            try: os.close(s)
            except: pass
    # close stdin pipe if needed
    if masters['stdin'] is None:
        try: p.stdin.close()
        except: pass
    # read outputs with timeout
    import time
    time.sleep(1)
    # try to read from pty masters
    for stream,m in masters.items():
        if m is not None:
            try:
                import fcntl
                flags = fcntl.fcntl(m, fcntl.F_GETFL)
                fcntl.fcntl(m, fcntl.F_SETFL, flags | os.O_NONBLOCK)
                try:
                    data = os.read(m, 65536)
                    print(f"{stream} pty data: {repr(data[:500])}")
                except Exception as e:
                    print(f"{stream} read err: {e}")
            except Exception as e:
                print(e)
            os.close(m)
    # get pipes
    try:
        out, err = p.communicate(timeout=2)
        print(f"rc={p.returncode} out={repr((out or b'')[:500])} err={repr((err or b'')[:500])}")
    except subprocess.TimeoutExpired:
        print("timeout, killing")
        p.kill()
        out, err = p.communicate()
        print(f"killed rc={p.returncode} out={repr((out or b'')[:500])} err={repr((err or b'')[:500])}")

test_case("all pipes (no tty)", False, False, False)
test_case("all pty", True, True, True)
test_case("stdin pty only", True, False, False)
test_case("stdout pty only", False, True, True)
PY
"}

