import subprocess
def run_script(args, timeout=5):
    full = " ".join(f"'{a}'" if " " in a else a for a in ["./executable"]+args)
    try:
        p=subprocess.run(["script","-qec",full,"/dev/null"], capture_output=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired as e:
        return "TIMEOUT", e.stdout or b"", e.stderr or b""
def res(out):
    m=b"\x1b[?25h"
    return out.split(m)[-1] if m in out else out

