fn is_known_flag(s: &str) -> bool {
    matches!(s, "-" | "--" | "--force-focus" | "-h" | "--help" | "-m" | "--pipe-msg-in" | "-M" | "--print-msg-in" | "--print-pwd-as-result" | "--read-only" | "--read0" | "--write0" | "-0" | "--null" | "-V" | "--version" | "-c" | "--config" | "-C" | "--extra-config" | "--on-load" | "--vroot")
}

