fn handle_pipe_msg(format: &str, args: &[String], is_print: bool) -> Result<i32, (i32, String)> {
    let expanded = match expand_placeholders(format, args) {
        Ok(s) => s,
        Err(e) => return Err((1, e)),
    };
    let msg = match parse_message_yaml(&expanded) {
        Ok(m) => m,
        Err(e) => return Err((1, e)),
    };
    let json = message_to_json(&msg);
    if is_print {
        // -M: print without newline to stdout
        print!("{}", json);
        // Need to flush?
        use std::io::Write;
        let _ = std::io::stdout().flush();
        Ok(0)
    } else {
        // -m: if XPLR_PIPE_MSG_IN env set, write to pipe with delimiter (first byte of existing content), else print with newline
        if let Ok(pipe_path) = env::var("XPLR_PIPE_MSG_IN") {
            let p = Path::new(&pipe_path);
            // Try to read existing content to detect delimiter
            match fs::read(p) {
                Ok(content) => {
                    if content.is_empty() {
                        return Err((1, "failed to detect delimmiter".to_string()));
                    }
                    let delim = content[0];
                    // Append json + delim to file
                    // Open in append mode
                    use std::io::Write;
                    match fs::OpenOptions::new().append(true).open(p) {
                        Ok(mut f) => {
                            let _ = f.write_all(json.as_bytes());
                            let _ = f.write_all(&[delim]);
                            Ok(0)
                        }
                        Err(e) => return Err((1, e.to_string())),
                    }
                }
                Err(e) => {
                    return Err((1, e.to_string()));
                }
            }
        } else {
            println!("{}", json);
            Ok(0)
        }
    }
}

