fn expand_placeholders(format: &str, values: &[String]) -> Result<String, String> {
    let chars: Vec<char> = format.chars().collect();
    let mut out = String::new();
    let mut val_idx = 0usize;
    let mut i = 0usize;
    while i < chars.len() {
        let col = i + 1;
        if chars[i] != '%' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        if i + 1 >= chars.len() {
            return Err("xplr -m: template ended with incomplete placeholder".to_string());
        }
        let nxt = chars[i+1];
        if nxt == '%' {
            out.push('%');
            i += 2;
            continue;
        } else if nxt == 's' {
            if val_idx >= values.len() {
                return Err(format!("xplr -m: placeholder missing value at column {}", col));
            }
            out.push_str(&values[val_idx]);
            val_idx += 1;
            i += 2;
            continue;
        } else if nxt == 'q' {
            if val_idx >= values.len() {
                return Err(format!("xplr -m: placeholder missing value at column {}", col));
            }
            let q = serde_json::to_string(&values[val_idx]).unwrap();
            out.push_str(&q);
            val_idx += 1;
            i += 2;
            continue;
        } else if nxt == '*' {
            if i + 2 >= chars.len() {
                return Err("xplr -m: template ended with incomplete placeholder".to_string());
            }
            let nxt2 = chars[i+2];
            if nxt2 == 's' {
                let rest = &values[val_idx..];
                let joined = rest.join(",");
                out.push_str(&joined);
                val_idx = values.len();
                i += 3;
                continue;
            } else if nxt2 == 'q' {
                let rest = &values[val_idx..];
                let quoted: Vec<String> = rest.iter().map(|v| serde_json::to_string(v).unwrap()).collect();
                let joined = quoted.join(",");
                out.push_str(&joined);
                val_idx = values.len();
                i += 3;
                continue;
            } else {
                let ph: String = chars[i..i+3].iter().collect();
                return Err(format!("xplr -m: invalid placeholder '{}' at column {}, use one of '%*s' or '%*q', or escape it using '%%'", ph, col+1));
            }
        } else {
            let ph: String = chars[i..i+2].iter().collect();
            return Err(format!("xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'", ph, col));
        }
    }
    if val_idx < values.len() {
        return Err("xplr -m: too many positional values, not enough positional placeholders".to_string());
    }
    Ok(out)
}

