fn parse_and_execute(prog_args: &[String]) -> Result<i32, (i32, String)> {
    let mut cli = Cli {
        help: false, version: false, force_focus: false, print_pwd_as_result: false,
        read_only: false, read0: false, write0: false, stdin_flag: false,
        config: None, extra_config: vec![], on_load: vec![],
        vroot: None, path: None, selection: vec![],
        pipe_msg: None, print_msg: None,
    };
    let mut i = 0usize;
    let mut positional_mode = false;
    let mut positionals: Vec<String> = vec![];
    let mut pipe_flag: Option<String> = None;
    let mut print_flag: Option<String> = None;
    let mut pipe_format: Option<String> = None;
    let mut pipe_args: Vec<String> = vec![];
    let mut print_format: Option<String> = None;
    let mut print_args: Vec<String> = vec![];

    while i < prog_args.len() {
        let arg = &prog_args[i];
        if pipe_flag.is_some() || print_flag.is_some() {
            if pipe_flag.is_some() {
                if pipe_format.is_none() { pipe_format = Some(arg.clone()); }
                else { pipe_args.push(arg.clone()); }
            } else {
                if print_format.is_none() { print_format = Some(arg.clone()); }
                else { print_args.push(arg.clone()); }
            }
            i += 1;
            continue;
        }
        if positional_mode {
            positionals.push(arg.clone());
            i += 1;
            continue;
        }
        match arg.as_str() {
            "--" => { positional_mode = true; i += 1; }
            "-" => { cli.stdin_flag = true; i += 1; }
            "--force-focus" => { cli.force_focus = true; i+=1; }
            "-h" | "--help" => { cli.help = true; i+=1; }
            "-V" | "--version" => { cli.version = true; i+=1; }
            "-m" | "--pipe-msg-in" => { pipe_flag = Some(arg.clone()); i+=1; }
            "-M" | "--print-msg-in" => { print_flag = Some(arg.clone()); i+=1; }
            "--print-pwd-as-result" => { cli.print_pwd_as_result = true; i+=1; }
            "--read-only" => { cli.read_only = true; i+=1; }
            "--read0" => { cli.read0 = true; i+=1; }
            "--write0" => { cli.write0 = true; i+=1; }
            "-0" | "--null" => { cli.read0 = true; cli.write0 = true; i+=1; }
            "-c" | "--config" => {
                if i+1 >= prog_args.len() {
                    let usage = if arg=="-c" { "usage: xplr -c PATH" } else { "usage: xplr --config PATH" };
                    return Err((1, usage.to_string()));
                }
                cli.config = Some(prog_args[i+1].clone());
                i+=2;
            }
            "--vroot" => {
                if i+1 >= prog_args.len() {
                    return Err((1, "usage: xplr --vroot PATH".to_string()));
                }
                cli.vroot = Some(prog_args[i+1].clone());
                i+=2;
            }
            "-C" | "--extra-config" => {
                i+=1;
                while i < prog_args.len() {
                    let nxt = &prog_args[i];
                    if nxt == "--" { break; }
                    if is_known_flag(nxt) { break; }
                    if nxt.starts_with('-') { break; }
                    cli.extra_config.push(nxt.clone());
                    i+=1;
                }
            }
            "--on-load" => {
                i+=1;
                while i < prog_args.len() {
                    let nxt = &prog_args[i];
                    if nxt == "--" { break; }
                    if is_known_flag(nxt) { break; }
                    if nxt.starts_with('-') { break; }
                    cli.on_load.push(nxt.clone());
                    i+=1;
                }
            }
            _ => {
                if arg.starts_with('-') {
                    return Err((1, format!("invalid argument: {:?}, try `-- {:?}` or `--help`", arg, arg)));
                } else {
                    positionals.push(arg.clone());
                    i+=1;
                }
            }
        }
    }

    if let Some(flag) = pipe_flag {
        if pipe_format.is_none() {
            let usage = if flag=="-m" { "usage: xplr -m FORMAT [ARGUMENT]..." } else { "usage: xplr --pipe-msg-in FORMAT [ARGUMENT]..." };
            return Err((1, usage.to_string()));
        }
        cli.pipe_msg = Some((flag, pipe_format.unwrap(), pipe_args));
    }
    if let Some(flag) = print_flag {
        if print_format.is_none() {
            let usage = if flag=="-M" { "usage: xplr -M FORMAT [ARGUMENT]..." } else { "usage: xplr --print-msg-in FORMAT [ARGUMENT]..." };
            return Err((1, usage.to_string()));
        }
        cli.print_msg = Some((flag, print_format.unwrap(), print_args));
    }

    if !positionals.is_empty() {
        cli.path = Some(positionals[0].clone());
        cli.selection = positionals[1..].to_vec();
    }

    if cli.pipe_msg.is_some() || cli.print_msg.is_some() {
        if cli.help {
            print!("{}", HELP_TEXT);
            return Ok(0);
        }
        if cli.version {
            print!("{}", VERSION_TEXT);
            return Ok(0);
        }
        if let Some((_, format, args)) = cli.pipe_msg {
            return handle_pipe_msg(&format, &args, false);
        }
        if let Some((_, format, args)) = cli.print_msg {
            return handle_pipe_msg(&format, &args, true);
        }
    }

    // Validate on_load messages
    for msg_str in &cli.on_load {
        if let Err(e) = parse_message_yaml(msg_str) {
            return Err((1, e));
        }
    }

    // Validate config/extra/vroot/paths
    if let Some(cfg) = &cli.config {
        let p = Path::new(cfg);
        if fs::metadata(p).is_err() {
            let abs = if p.is_absolute() { p.to_path_buf() } else { env::current_dir().unwrap_or(PathBuf::from(".")).join(p) };
            return Err((1, format!("path doesn't exist: {}", abs.display())));
        }
    }
    for ec in &cli.extra_config {
        let p = Path::new(ec);
        if fs::metadata(p).is_err() {
            let abs = if p.is_absolute() { p.to_path_buf() } else { env::current_dir().unwrap_or(PathBuf::from(".")).join(p) };
            return Err((1, format!("path doesn't exist: {}", abs.display())));
        }
    }
    if let Some(vr) = &cli.vroot {
        let p = Path::new(vr);
        if fs::metadata(p).is_err() {
            let abs = if p.is_absolute() { p.to_path_buf() } else { env::current_dir().unwrap_or(PathBuf::from(".")).join(p) };
            return Err((1, format!("path doesn't exist: {}", abs.display())));
        }
    }
    let mut to_check: Vec<String> = vec![];
    if let Some(p) = &cli.path {
