                // Implement below.
                if a == b { return std::cmp::Ordering::Equal; }
                // Fallback: compare original with custom where lower < upper for same letter
                let mut ac = a.chars();
                let mut bc = b.chars();
                loop {
                    match (ac.next(), bc.next()) {
                        (None, None) => return std::cmp::Ordering::Equal,
                        (None, Some(_)) => return std::cmp::Ordering::Less,
                        (Some(_), None) => return std::cmp::Ordering::Greater,
                        (Some(x), Some(y)) => {
                            if x == y { continue; }
                            if x.to_lowercase().to_string() == y.to_lowercase().to_string() {
                                // same letter different case: lower first
                                if x.is_lowercase() && y.is_uppercase() { return std::cmp::Ordering::Less; }
