fn apply_message(msg: &Message, pwd: &mut PathBuf, nodes: &mut Vec<PathBuf>, focus: &mut PathBuf, focus_idx: &mut usize, selection: &mut Vec<PathBuf>, vroot: &Option<PathBuf>, cwd: &PathBuf, force_focus: bool) -> Result<Option<String>, String> {
    match msg {
        Message::Quit => Ok(Some("Quit".to_string())),
        Message::Terminate => Ok(Some("Terminate".to_string())),
        Message::PrintPwdAndQuit => Ok(Some("PrintPwdAndQuit".to_string())),
        Message::PrintFocusPathAndQuit => Ok(Some("PrintFocusPathAndQuit".to_string())),
        Message::PrintSelectionAndQuit => Ok(Some("PrintSelectionAndQuit".to_string())),
        Message::PrintResultAndQuit => Ok(Some("PrintResultAndQuit".to_string())),
        Message::PrintAppStateAndQuit => Ok(Some("PrintAppStateAndQuit".to_string())),
        Message::FocusNext => {
            if !nodes.is_empty() {
                *focus_idx = (*focus_idx + 1) % nodes.len();
                *focus = nodes[*focus_idx].clone();
            }
            Ok(None)
        }
        Message::FocusPrevious => {
            if !nodes.is_empty() {
                if *focus_idx == 0 { *focus_idx = nodes.len() - 1; }
                else { *focus_idx -= 1; }
                *focus = nodes[*focus_idx].clone();
            }
            Ok(None)
        }
        Message::FocusFirst => {
            if !nodes.is_empty() { *focus_idx = 0; *focus = nodes[0].clone(); }
            Ok(None)
        }
        Message::FocusLast => {
            if !nodes.is_empty() { *focus_idx = nodes.len()-1; *focus = nodes[*focus_idx].clone(); }
            Ok(None)
        }
        Message::FocusPath(s) => {
            let p = Path::new(s);
            let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
            // If path is dir and not force-focus? Actually FocusPath should focus on path, even if dir? From earlier, FocusPath: /tmp/probe1/b.txt with pwd probe1 gave focus b.txt. Good. What if FocusPath is dir? Probably focus dir itself? Or enter? Need to handle. For now, if dir, set pwd to dir and focus to first child? Or focus to dir? Let's check: FocusPath to dir vs file? Not tested. For now, if dir, set pwd to dir, focus to first child (like ChangeDirectory?).
            // Actually FocusPath vs ChangeDirectory vs Enter: FocusPath focuses, ChangeDirectory changes pwd, Enter enters if dir else... Hard.
            // Simplify: if path exists and is dir, set pwd to it, refresh nodes, focus to first; if file, set focus to it (and pwd to parent? Or keep pwd?).
            // From earlier, FocusPath: /tmp/probe1/b.txt with pwd probe1: pwd stayed probe1? Or changed to parent of b.txt (which is probe1, same)? Good. So for file, pwd is parent (which may be same as current pwd). Good.
            // Implement: if file, pwd = parent, focus = file; if dir, pwd = dir, focus = first child.
            if let Ok(meta) = fs::metadata(&abs) {
                if meta.is_dir() {
                    *pwd = abs.clone();
                    *nodes = list_dir_sorted(pwd);
                    if !nodes.is_empty() { *focus_idx = 0; *focus = nodes[0].clone(); }
                    else { *focus = pwd.clone(); }
                } else {
                    // file
                    if let Some(parent) = abs.parent() {
                        // Only change pwd if parent != current pwd? Or always? For FocusPath to file in different dir, should pwd change to parent? Probably yes (to show file). Let's do: pwd = parent, nodes = list, focus = file.
                        *pwd = parent.to_path_buf();
                        *nodes = list_dir_sorted(pwd);
                        // Find focus index
                        if let Some(pos) = nodes.iter().position(|x| x == &abs) {
                            *focus_idx = pos;
                            *focus = abs;
                        } else {
                            // file not in nodes (hidden? Or outside?)? Just set focus to file.
                            *focus = abs;
                        }
                    } else {
                        *focus = abs;
                    }
                }
            }
            Ok(None)
        }
        Message::FocusByIndex(idx) => {
            if !nodes.is_empty() && *idx < nodes.len() {
                *focus_idx = *idx;
                *focus = nodes[*focus_idx].clone();
            }
            Ok(None)
        }
        Message::FocusByFileName(name) => {
            if let Some(pos) = nodes.iter().position(|x| x.file_name().and_then(|s| s.to_str()) == Some(name)) {
                *focus_idx = pos;
                *focus = nodes[pos].clone();
            }
            Ok(None)
        }
        Message::Select => {
            if !selection.contains(focus) {
                selection.push(focus.clone());
            }
            Ok(None)
        }
        Message::SelectAll => {
            selection.clear();
            selection.extend(nodes.clone());
            Ok(None)
        }
        Message::SelectPath(s) => {
            let p = Path::new(s);
            let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
            if !selection.contains(&abs) {
                selection.push(abs);
            }
            Ok(None)
        }
        Message::UnSelect => {
            selection.retain(|x| x != focus);
            Ok(None)
        }
        Message::UnSelectAll => { selection.clear(); Ok(None) }
        Message::UnSelectPath(s) => {
            let p = Path::new(s);
            let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
            selection.retain(|x| x != &abs);
            Ok(None)
        }
        Message::ToggleSelection => {
            if selection.contains(focus) { selection.retain(|x| x != focus); }
            else { selection.push(focus.clone()); }
            Ok(None)
        }
