            Ok(None)
        }
        Message::ToggleSelectionByPath(s) => {
            let p = Path::new(s);
            let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
            if selection.contains(&abs) { selection.retain(|x| x != &abs); }
            else { selection.push(abs); }
            Ok(None)
        }
        Message::ClearSelection => { selection.clear(); Ok(None) }
        Message::ChangeDirectory(s) => {
            let p = Path::new(s);
            let abs = if p.is_absolute() { p.to_path_buf() } else { pwd.join(p) };
            if abs.is_dir() {
                *pwd = abs;
                *nodes = list_dir_sorted(pwd);
                if !nodes.is_empty() { *focus_idx = 0; *focus = nodes[0].clone(); }
                else { *focus = pwd.clone(); }
            }
            Ok(None)
        }
        Message::Enter => {
            if focus.is_dir() {
                *pwd = focus.clone();
                *nodes = list_dir_sorted(pwd);
                if !nodes.is_empty() { *focus_idx = 0; *focus = nodes[0].clone(); }
                else { *focus = pwd.clone(); }
            }
            Ok(None)
        }
        Message::Back => {
            if let Some(parent) = pwd.parent() {
                // Check vroot containment? If vroot set and parent outside, don't go? Original would prevent? For now, allow but check vroot.
                if let Some(vr) = vroot {
                    if !parent.starts_with(vr) && parent != vr {
                        // Don't go outside vroot
                        return Ok(None);
                    }
                }
                *pwd = parent.to_path_buf();
                *nodes = list_dir_sorted(pwd);
                if !nodes.is_empty() { *focus_idx = 0; *focus = nodes[0].clone(); }
                else { *focus = pwd.clone(); }
            }
            Ok(None)
        }
        Message::FocusNextSelection => {
            // Focus next selected? Find next selected after current focus index
            if !nodes.is_empty() && !selection.is_empty() {
                for offset in 1..=nodes.len() {
                    let idx = (*focus_idx + offset) % nodes.len();
                    if selection.contains(&nodes[idx]) {
                        *focus_idx = idx;
                        *focus = nodes[idx].clone();
                        break;
                    }
                }
            }
            Ok(None)
        }
        Message::FocusPreviousSelection => {
            if !nodes.is_empty() && !selection.is_empty() {
                for offset in 1..=nodes.len() {
                    let idx = (*focus_idx + nodes.len() - offset % nodes.len()) % nodes.len();
                    if selection.contains(&nodes[idx]) {
                        *focus_idx = idx;
                        *focus = nodes[idx].clone();
                        break;
                    }
                }
            }
            Ok(None)
        }
        // For other messages, treat as no-op (to allow tests with those messages to succeed without error, even if not fully implemented)
        _ => Ok(None),
    }
}
