use serde::{Deserialize, Serialize};
#[derive(Debug, Serialize, Deserialize)]
enum Msg {
    Quit,
    FocusPath(String),
    FocusByIndex(usize),
}
fn main() {
    for s in ["Quit", "FocusPath: /tmp", "FocusByIndex: 5", "FocusPath: test", "Call: {command: test}"] {
        // Try via Value
        match serde_yaml::from_str::<serde_yaml::Value>(s) {
            Ok(v) => {
                println!("YAML Value for {:?} => {:?}", s, v);
                // Convert to json value via serde_json::to_value?
                // serde_yaml::Value to serde_json::Value via serialization?
                let json_str = serde_json::to_string(&v).unwrap();
                println!("  json str: {}", json_str);
                match serde_json::from_str::<Msg>(&json_str) {
                    Ok(m) => println!("  OK {:?}", m),
                    Err(e) => println!("  JSON ERR {}", e),
                }
            }
            Err(e) => println!("YAML ERR {:?} => {}", s, e),
        }
    }
}
EOF
