use serde::{Deserialize, Serialize};
#[derive(Debug, Serialize, Deserialize)]
enum Msg {
    Quit,
    FocusPath(String),
    FocusByIndex(usize),
    Call(Command),
}
#[derive(Debug, Serialize, Deserialize)]
struct Command {
    command: String,
    args: Option<Vec<String>>,
}
fn parse_via_json(s: &str) -> Result<Msg, String> {
    let yaml_val: serde_yaml::Value = serde_yaml::from_str(s).map_err(|e| format!("YAML_ERR: {}", e))?;
    let json_val = serde_json::to_value(&yaml_val).map_err(|e| format!("JSON_CONV_ERR: {}", e))?;
    let msg: Msg = serde_json::from_value(json_val).map_err(|e| format!("JSON_ERR: {}", e))?;
    Ok(msg)
}
fn main() {
    for s in ["Quit", "FocusPath: /tmp", "FocusByIndex: 5", "Call: test", "Hello", "", " ", "%%", "FocusPath: 5"] {
        match parse_via_json(s) {
            Ok(m) => println!("OK {:?} => {}", s, serde_json::to_string(&m).unwrap()),
            Err(e) => println!("ERR {:?} => {}", s, e),
        }
        // Also direct for comparison
        match serde_yaml::from_str::<Msg>(s) {
            Ok(m) => println!("  direct OK {:?}", m),
            Err(e) => println!("  direct ERR {}", e),
        }
    }
}
EOF
